int64_t mbpp225_find_Min(const int64_t *arr, int64_t arr_n, int64_t low, int64_t high) {
  if (low > high) return -1;
  if (low == high) return arr[low];

  while (low < high) {
    int64_t mid = (high + low) / 2;
    if (arr[mid] > arr[high]) {
      low = mid + 1;
    } else if (arr[mid] < arr[high]) {
      high = mid;
    } else {
      high--;
    }
  }
  return arr[low];
}

